/*!40000 ALTER TABLE `chunks` DISABLE KEYS */;
INSERT INTO `chunks` VALUES
(1,1,1,1,1,0,'Comment ça marche','On crée son assistant en trois étapes : on choisit son métier, on lui donne ses documents (PDF, Word, tableurs), des photos d\'affiches ou de menus, le lien de son site ou du texte, puis on l\'installe sur son site avec une ligne de code ou sur WhatsApp. On le teste dans l\'espace client avant de le publier.\n\nL\'assistant répond aux clients uniquement à partir de ces contenus. Quand il ne sait pas, il le dit et propose de contacter l\'équipe ; la question apparaît dans la liste des questions sans réponse, pour que l\'entreprise la complète en une minute. Quand le client demande une personne, l\'entreprise est prévenue tout de suite (par e-mail ou sur WhatsApp, au choix) et reprend la conversation depuis sa boîte de réception.\n\nL\'entreprise peut modifier à tout moment la consigne de son assistant : ton, tutoiement ou vouvoiement, règles du métier, informations à toujours donner.',221,'','openai:text-embedding-3-small','2026-10-01 02:51:03','2026-10-01 02:51:03'),
(2,1,1,2,2,0,'Prix et tarifs','Question : combien ça coûte ? quel est le prix ? quels sont les tarifs ? c\'est combien ?\nRéponse : on démarre par un essai gratuit de 14 jours, sans carte bancaire (jusqu\'à 100 réponses). Ensuite, les offres payantes vont de 10 000 FCFA à 120 000 FCFA par mois, selon le nombre d\'assistants, de réponses et de messages WhatsApp : Essentiel à 10 000 FCFA par mois, Bon plan à 25 000 FCFA par mois, Pro à 40 000 FCFA par mois, Business à 120 000 FCFA par mois.',115,'','openai:text-embedding-3-small','2026-10-01 02:51:06','2026-10-01 02:51:06'),
(3,1,1,3,3,0,'Offre gratuite et essai','Question : y a-t-il une offre gratuite ? c\'est gratuit ? puis-je essayer avant de payer ?\nRéponse : oui, l\'essai gratuit dure 14 jours, sans carte bancaire et sans engagement. À la fin de l\'essai, l\'assistant se met en pause et les contenus sont conservés jusqu\'au choix d\'une offre.',71,'','openai:text-embedding-3-small','2026-10-01 02:51:09','2026-10-01 02:51:09'),
(4,1,1,4,4,0,'Engagement','Question : y a-t-il un engagement ? puis-je arrêter quand je veux ?\nRéponse : non, il n\'y a aucun engagement : on change d\'offre ou on arrête quand on veut.',39,'','openai:text-embedding-3-small','2026-10-01 02:51:12','2026-10-01 02:51:12'),
(5,1,1,5,5,0,'Offres et limites','Découverte : gratuit. 14 jours pour essayer, sans carte bancaire. 1 assistant(s), 100 réponses par mois, 4 sources, 10 pages lues par site, 1 utilisateur(s). Essentiel : 10 000 FCFA par mois (soit 7 500 KMF ou 15 € ou 17 $ ou 165 DH). Votre assistant sur votre site web. 1 assistant(s), 1000 réponses par mois, 20 sources, 50 pages lues par site, 2 utilisateur(s). Bon plan : 25 000 FCFA par mois (soit 18 750 KMF ou 38 € ou 43 $ ou 410 DH). Un assistant complet, sur votre site et WhatsApp, au juste prix. 1 assistant(s), 2000 réponses par mois, 40 sources, 100 pages lues par site, 3 utilisateur(s), 800 messages WhatsApp par mois, 100 messages vocaux par mois. Inclus : WhatsApp, Messages vocaux : écoute et réponse audio. Pro : 40 000 FCFA par mois (soit 30 000 KMF ou 60 € ou 70 $ ou 660 DH). Pour une activité qui reçoit beaucoup de messages. 3 assistant(s), 5000 réponses par mois, 60 sources, 200 pages lues par site, 5 utilisateur(s), 2500 messages WhatsApp par mois, 300 messages vocaux par mois. Inclus : WhatsApp, Modèles de messages WhatsApp, Sans publicité « Propulsé par », Messages vocaux : écoute et réponse audio, Import de vos discussions WhatsApp (apprentissage du style).',298,'','openai:text-embedding-3-small','2026-10-01 02:51:15','2026-10-01 02:51:15'),
(6,1,1,5,5,1,'Offres et limites','WhatsApp, Sans publicité « Propulsé par », Messages vocaux : écoute et réponse audio, Import de vos discussions WhatsApp (apprentissage du style).\n\n\n\nBusiness : 120 000 FCFA par mois (soit 90 000 KMF ou 180 € ou 205 $ ou 1 975 DH). Plusieurs assistants, une équipe, un suivi dédié. 10 assistant(s), 15000 réponses par mois, 300 sources, 500 pages lues par site, 15 utilisateur(s), 10000 messages WhatsApp par mois, 1500 messages vocaux par mois. Inclus : WhatsApp, Modèles de messages WhatsApp, Sans publicité « Propulsé par », Assistance prioritaire, Messages vocaux : écoute et réponse audio, Import de vos discussions WhatsApp (apprentissage du style).',164,'','openai:text-embedding-3-small','2026-10-01 02:51:15','2026-10-01 02:51:15'),
(7,1,1,6,6,0,'Comment payer','Question : comment payer ? quels moyens de paiement ? puis-je payer par Orange Money ou Moov Money ?\nRéponse : par Orange Money, Moov Money, Coris Money ou virement. L\'entreprise envoie la référence du paiement et l\'offre est activée dès réception. Aucune carte bancaire n\'est demandée.',72,'','openai:text-embedding-3-small','2026-10-01 02:51:17','2026-10-01 02:51:17'),
(8,1,1,7,7,0,'Monnaies','Question : en quelle monnaie sont les prix ? puis-je payer en euro ou en franc comorien ?\nRéponse : les prix sont affichés en FCFA, en franc comorien, en euro, en dollar ou en dirham marocain, au choix du visiteur.',54,'','openai:text-embedding-3-small','2026-10-01 02:51:19','2026-10-01 02:51:19'),
(9,1,1,8,8,0,'Messages WhatsApp : faut-il payer en plus ?','Question : les messages WhatsApp sont-ils payants en plus ? faut-il un compte Meta ?\nRéponse : non. Un volume mensuel de messages WhatsApp est inclus dans les offres avec WhatsApp, sans compte à ouvrir chez Meta ni carte bancaire. Si le volume est dépassé, on recharge des messages par Mobile Money.',75,'','openai:text-embedding-3-small','2026-10-01 02:51:21','2026-10-01 02:51:21'),
(10,1,1,9,9,0,'WhatsApp','L\'assistant peut répondre sur un numéro WhatsApp Business. L\'activation est faite avec l\'équipe de Kouma : compte WhatsApp Business, vérification du numéro, configuration. L\'entreprise garde la propriété de son numéro. Les conversations arrivent dans la boîte de réception ; quand l\'entreprise répond elle-même, l\'assistant se tait pour cette conversation.\n\nWhatsApp n\'autorise le texte libre que dans les 24 heures qui suivent le dernier message du client. Au-delà, il faut un modèle de message approuvé : la plateforme permet de les créer, de suivre leur approbation et de les envoyer (offres Pro et Business). Les offres sans WhatsApp incluent le widget de site web.',168,'','openai:text-embedding-3-small','2026-10-01 02:51:22','2026-10-01 02:51:22'),
(11,1,1,10,10,0,'Langues et messages vocaux','L\'assistant répond dans la langue du client, parmi celles que l\'entreprise a choisies. Langues bien maîtrisées : Français, Anglais, Arabe et Swahili. Langues locales « assistées » (phrases courtes et simples, à tester avec ses propres phrases) : Bambara, Dioula, Peul, Wolof. Langues expérimentales (très peu de données, l\'assistant répond aussi en français) : Mooré, Shikomori.\n\nLes clients peuvent envoyer des messages vocaux, sur WhatsApp comme sur le site web : l\'assistant les écoute et répond par écrit, ou en audio pour le français, l\'anglais et l\'arabe. Un volume mensuel de messages vocaux est inclus selon l\'offre (à partir de l\'offre « Bon plan »).',165,'','openai:text-embedding-3-small','2026-10-01 02:51:23','2026-10-01 02:51:23'),
(12,1,1,11,11,0,'Demandes, commandes et alertes','L\'assistant reconnaît une commande, une demande de rendez-vous, une demande de devis ou une demande de parler à une personne. Il prépare la demande avec les coordonnées du client et prévient l\'entreprise. Toutes les demandes arrivent dans la page « Demandes ».\n\nL\'entreprise choisit comment être prévenue : par e-mail, par un message WhatsApp sur son numéro, sur celui de chaque membre de l\'équipe, ou sur un autre numéro de son choix, avec un rappel si personne ne répond. Les commandes et les rendez-vous sont toujours confirmés par l\'entreprise, jamais par le robot.',143,'','openai:text-embedding-3-small','2026-10-01 02:51:26','2026-10-01 02:51:26'),
(13,1,1,12,12,0,'Sources de connaissances','Documents PDF, Word, texte, tableurs CSV, photos (le texte des affiches et des menus est lu), pages de site web (relues automatiquement chaque jour ou chaque semaine), textes collés, questions et réponses. Pour une page Facebook ou Instagram, le client colle le lien puis le contenu de sa page : Meta interdit la lecture automatique de ces pages ; une connexion officielle est possible pour ceux qui l\'administrent.\n\nAvec l\'offre Pro (ou en option), l\'entreprise peut importer une discussion WhatsApp exportée : l\'assistant apprend son style et ses réponses habituelles. Le fichier n\'est pas conservé et les données personnelles des clients sont masquées.',164,'','openai:text-embedding-3-small','2026-10-01 02:51:28','2026-10-01 02:51:28'),
(14,1,1,13,13,0,'Données et sécurité','Chaque entreprise a un espace isolé : ses documents ne servent qu\'à son assistant. Les clés d\'accès sont chiffrées, les échanges passent par HTTPS et l\'entreprise peut supprimer ses contenus à tout moment. Pour produire une réponse, les extraits pertinents et la question sont envoyés à un fournisseur d\'intelligence artificielle.',83,'','openai:text-embedding-3-small','2026-10-01 02:51:30','2026-10-01 02:51:30'),
(15,1,1,14,14,0,'Installer Kouma sur son téléphone','L\'espace client s\'installe comme une application. Sur iPhone et iPad : ouvrir le site dans Safari, toucher Partager, puis « Sur l\'écran d\'accueil ». Sur Android : menu du navigateur, puis « Installer l\'application ». Une icône apparaît avec les autres applications, sans rien télécharger.',72,'','openai:text-embedding-3-small','2026-10-01 02:51:32','2026-10-01 02:51:32'),
(16,1,1,15,15,0,'Accompagnement et contact','Pour ceux qui ne veulent pas s\'en occuper, l\'équipe de Kouma gère tout : elle crée l\'assistant, lit les documents, active WhatsApp et met à jour les tarifs. Le devis est clair et sans engagement.\n\nContact : e-mail contac@kouma.site.\n\nUne offre pour développeurs permet d\'appeler l\'assistant depuis sa propre application : tout est expliqué sur la page https://kouma.site/developpeurs. Des guides pratiques (prix d\'un chatbot WhatsApp, créer son assistant, métiers et pays) sont réunis sur https://kouma.site/ressources.',130,'','openai:text-embedding-3-small','2026-10-01 02:51:34','2026-10-01 02:51:34'),
(17,1,1,16,16,0,'Un chatbot WhatsApp qui répond à vos clients à votre place','Vos clients vous écrivent sur WhatsApp à toute heure : pour un prix, un horaire, une livraison. Kouma lit vos documents et répond tout de suite, avec vos vraies informations. Quand la question dépasse le robot, il vous passe la main.\n\nUn chatbot WhatsApp qui répond à vos clients à votre place > Ce que fait votre chatbot WhatsApp\n\n- Il répond sur votre numéro WhatsApp avec vos prix, vos horaires, vos adresses et vos conditions de livraison.\n- Il comprend les messages vocaux et répond par écrit, ou en audio si vous le souhaitez.\n- Il prend une commande, un rendez-vous ou une demande de devis, et vous prévient tout de suite, par e-mail ou sur votre propre numéro WhatsApp.\n- Il vous passe la main quand un client demande une personne ou exprime un mécontentement.\n- Il parle plusieurs langues : français, anglais, arabe, et des langues locales avec leurs limites annoncées franchement.',223,'','openai:text-embedding-3-small','2026-10-01 02:51:38','2026-10-01 02:51:38'),
(18,1,1,16,16,1,'Un chatbot WhatsApp qui répond à vos clients à votre place > Il ne répond qu\'avec ce que vous lui donnez','Vous envoyez vos documents (PDF, Word, tableaux), des photos d\'affiches ou de menus, le lien de votre site ou du texte collé. Kouma les découpe et s\'en souvient. Chaque réponse s\'appuie sur ces sources, et quand l\'information manque, l\'assistant le dit au lieu de deviner.\nVous voyez ensuite la liste des questions restées sans réponse et vous y répondez en une minute : l\'assistant s\'améliore avec votre activité.\n\nUn chatbot WhatsApp qui répond à vos clients à votre place > Comment démarrer\n\n1. Créez votre assistant et envoyez vos documents, vos photos ou le lien de votre site.\n2. Testez-le dans votre espace avec les questions de vos clients.\n3. Activez WhatsApp : notre équipe configure le numéro avec vous (compte WhatsApp Business, vérification, branchement).\n4. Suivez les conversations et reprenez la main quand vous le souhaitez.',211,'','openai:text-embedding-3-small','2026-10-01 02:51:38','2026-10-01 02:51:38'),
(19,1,1,16,16,2,'Un chatbot WhatsApp qui répond à vos clients à votre place > WhatsApp : ce qu\'il faut savoir','WhatsApp n\'autorise le texte libre que dans les 24 heures qui suivent le dernier message du client. Au-delà, il faut un modèle de message approuvé : Kouma vous permet de les préparer et de les suivre depuis votre espace.\nLes messages WhatsApp sont inclus dans votre offre, avec un volume mensuel : vous n\'avez ni compte à ouvrir chez Meta, ni carte bancaire à saisir.\n\nUn chatbot WhatsApp qui répond à vos clients à votre place > Prix\n\nL\'offre Bon plan à 25 000 FCFA par mois donne un assistant sur votre site et sur WhatsApp, avec 800 messages WhatsApp et 100 messages vocaux inclus. L\'offre Pro à 40 000 FCFA par mois ajoute plusieurs assistants, les modèles de messages et l\'import de vos discussions. Essai gratuit de 14 jours, sans carte bancaire.\n\nQuestion : Un chatbot WhatsApp peut-il inventer un prix ?\nRéponse : Kouma est construit pour ne pas le faire : il ne répond qu\'à partir de vos documents. Quand l\'information manque, il le dit et propose de contacter votre équipe.\n\nQuestion : Faut-il un numéro WhatsApp Business ?\nRéponse : Il faut un numéro que vous contrôlez et qui n\'est pas déjà enregistré sur WhatsApp. Notre équipe vous guide pour la vérification et la configuration.',299,'','openai:text-embedding-3-small','2026-10-01 02:51:38','2026-10-01 02:51:38'),
(20,1,1,16,16,3,'Un chatbot WhatsApp qui répond à vos clients à votre place > Prix','Il faut un numéro que vous contrôlez et qui n\'est pas déjà enregistré sur WhatsApp. Notre équipe vous guide pour la vérification et la configuration.\n\n\n\nQuestion : Mes clients savent-ils qu\'ils parlent à un robot ?\nRéponse : Oui : l\'assistant se présente comme l\'assistant virtuel de votre entreprise et propose de vous passer la main à tout moment.\n\nQuestion : Puis-je répondre moi-même à un client ?\nRéponse : Oui. Dès que vous répondez depuis la boîte de réception, l\'assistant se tait pour cette conversation, et les rappels s\'arrêtent.\n\nQuestion : Combien de messages sont inclus ?\nRéponse : Chaque offre inclut un volume mensuel de messages WhatsApp et de messages vocaux ; au-delà, vous rechargez par Mobile Money.\n\nPage du site : https://kouma.site/chatbot-whatsapp',194,'','openai:text-embedding-3-small','2026-10-01 02:51:38','2026-10-01 02:51:38'),
(21,1,1,17,17,0,'Un assistant virtuel pour votre site web, installé en une ligne','Vos visiteurs posent toujours les mêmes questions : prix, horaires, livraison, rendez-vous. Avec Kouma, une bulle de discussion répond à la place de votre équipe, avec vos propres informations, et laisse un moyen de vous joindre quand il le faut.\n\nUn assistant virtuel pour votre site web, installé en une ligne > Une ligne de code, sur n\'importe quel site\n\nVous copiez une ligne dans votre site (WordPress, Wix, Shopify ou site sur mesure : tout site qui accepte un extrait de code). Le widget s\'affiche dans une zone isolée : il n\'abîme pas votre mise en page, et votre mise en page ne l\'abîme pas. Vous choisissez sa couleur, sa position, son titre et les domaines autorisés.\n\nUn assistant virtuel pour votre site web, installé en une ligne > Ce que vos visiteurs peuvent faire\n\n- Poser leur question par écrit, ou la dicter avec le micro.\n- Écouter une réponse, la copier, dire si elle était utile.\n- Choisir leur langue parmi celles que parle votre assistant.\n- Démarrer une nouvelle conversation, ou continuer sur WhatsApp en un geste.\n- Demander à parler à une personne : vous êtes prévenu tout de suite.',278,'','openai:text-embedding-3-small','2026-10-01 02:51:41','2026-10-01 02:51:41'),
(22,1,1,17,17,1,'Un assistant virtuel pour votre site web, installé en une ligne > Ce que vous gagnez','- Moins de questions répétitives, et des réponses à toute heure, y compris la nuit et le week-end.\n- La liste des questions sans réponse : ce que vos visiteurs cherchent et que votre site ne dit pas encore.\n- Les demandes de commande, de rendez-vous et de devis regroupées au même endroit.\n\nUn assistant virtuel pour votre site web, installé en une ligne > Sans site web ?\n\nVous pouvez aussi partager une page de démonstration par lien, ou publier votre assistant sur WhatsApp. Le site web n\'est pas obligatoire.\n\nQuestion : Le widget ralentit-il mon site ?\nRéponse : Non : il se charge après votre page, sans dépendance, et reste isolé du reste du site.\n\nQuestion : Puis-je limiter les sites où il fonctionne ?\nRéponse : Oui : une liste blanche de domaines protège votre assistant contre l\'usage depuis un site tiers.\n\nQuestion : Les visiteurs doivent-ils donner leur nom ?\nRéponse : Seulement si vous le souhaitez : vous pouvez demander un nom et un téléphone avant la discussion.\n\nQuestion : Puis-je retirer la mention « Propulsé par » ?\nRéponse : Oui, avec l\'offre Pro ou Business.\n\nPage du site : https://kouma.site/assistant-virtuel-site-web',287,'','openai:text-embedding-3-small','2026-10-01 02:51:41','2026-10-01 02:51:41'),
(23,1,1,18,18,0,'Réponse automatique sur WhatsApp Business : que choisir ?','Vous voulez que vos clients reçoivent une réponse même quand vous ne pouvez pas écrire. L\'application WhatsApp Business offre déjà quelques outils ; un assistant va plus loin. Voici la différence, sans détour.\n\nRéponse automatique sur WhatsApp Business : que choisir ? > Ce que propose l\'application WhatsApp Business\n\n- Un message d\'accueil, envoyé quand un client vous écrit pour la première fois ou après une période sans échange.\n- Un message d\'absence, envoyé en dehors de vos horaires.\n- Des réponses rapides : des phrases enregistrées que vous insérez en tapant un raccourci.\n- Des étiquettes pour classer vos conversations, à poser à la main.\n\nRéponse automatique sur WhatsApp Business : que choisir ? > Leurs limites\n\nCes messages sont toujours les mêmes : ils ne répondent pas à la question posée. Un client qui demande « vous livrez à Bobo ? » reçoit le même message d\'accueil que celui qui demande un horaire, et doit attendre votre réponse.',239,'','openai:text-embedding-3-small','2026-10-01 02:51:46','2026-10-01 02:51:46'),
(24,1,1,18,18,1,'Réponse automatique sur WhatsApp Business : que choisir ? > Ce qu\'apporte un assistant','- Il répond à la question posée, avec vos prix et vos conditions, tout de suite.\n- Il prend les commandes et les rendez-vous, et vous prévient.\n- Il vous passe la main quand c\'est nécessaire, avec la conversation déjà résumée.\n- Il garde la trace de ce qu\'on lui demande et que vous n\'avez pas encore écrit quelque part.\n\nRéponse automatique sur WhatsApp Business : que choisir ? > Les deux se complètent\n\nVous pouvez garder vos messages d\'accueil et vos étiquettes dans l\'application, et confier les réponses à l\'assistant. Kouma indique pour chaque demande l\'étiquette à poser à la main si vous utilisez aussi l\'application (WhatsApp ne permet pas de les poser automatiquement).\n\nQuestion : Le message d\'absence suffit-il ?\nRéponse : Il rassure le client mais ne répond pas à sa question. Pour un commerce qui reçoit beaucoup de demandes, un assistant fait gagner plus de temps.\n\nQuestion : Un assistant peut-il envoyer un message d\'accueil ?\nRéponse : Oui : il accueille chaque client, se présente et propose des réponses rapides adaptées à votre métier.',265,'','openai:text-embedding-3-small','2026-10-01 02:51:46','2026-10-01 02:51:46'),
(25,1,1,18,18,2,'Réponse automatique sur WhatsApp Business : que choisir ? > Les deux se complètent','envoyer un message d\'accueil ?\nRéponse : Oui : il accueille chaque client, se présente et propose des réponses rapides adaptées à votre métier.\n\n\n\nQuestion : Puis-je reprendre la conversation ?\nRéponse : Oui, à tout moment, depuis la boîte de réception ou votre téléphone si vous utilisez l\'application.\n\nPage du site : https://kouma.site/reponse-automatique-whatsapp-business',94,'','openai:text-embedding-3-small','2026-10-01 02:51:46','2026-10-01 02:51:46'),
(26,1,1,19,19,0,'Combien coûte un chatbot WhatsApp pour une petite entreprise ?','Le prix d\'un chatbot WhatsApp se compose de plusieurs postes, et tous ne sont pas toujours annoncés. Voici comment les repérer, ce qui les fait varier, et combien coûte Kouma.\n\nCombien coûte un chatbot WhatsApp pour une petite entreprise ? > Les quatre postes à regarder\n\n1. L\'abonnement à la plateforme : c\'est le prix mensuel de l\'outil, avec ses limites (nombre d\'assistants, de réponses, de sources).\n2. Les messages WhatsApp : Meta facture les messages selon leur catégorie (marketing, utilitaire, authentification, service) et le pays. Une plateforme peut les inclure dans son prix, ou les facturer à part.\n3. L\'intelligence artificielle : chaque réponse générée a un coût. Une offre honnête fixe un nombre de réponses par mois.\n4. La mise en route : configuration du numéro, vérification de l\'entreprise, rédaction des consignes. Certains prestataires la facturent, d\'autres l\'incluent.',224,'','openai:text-embedding-3-small','2026-10-01 02:51:50','2026-10-01 02:51:50'),
(27,1,1,19,19,1,'Combien coûte un chatbot WhatsApp pour une petite entreprise ? > Les frais qu\'on découvre trop tard','- Des messages WhatsApp facturés sur votre propre carte bancaire, à payer en plus de l\'abonnement.\n- Un nombre de conversations limité sans dire ce qui se passe au-delà.\n- Des fonctions essentielles (passage à un humain, plusieurs langues, statistiques) réservées à l\'offre la plus chère.\n- Un prix en dollars ou en euros, sans possibilité de payer par Mobile Money.\n\nCombien coûte un chatbot WhatsApp pour une petite entreprise ? > Les prix de Kouma\n\nLes messages WhatsApp sont inclus dans chaque offre qui comprend WhatsApp, avec un volume mensuel. Vous payez par Orange Money, Moov Money, Coris Money ou virement, en FCFA, en franc comorien, en euro, en dollar ou en dirham.\n- Essai gratuit : 14 jours, 100 réponses, sans carte bancaire.\n- Essentiel, 10 000 FCFA par mois : un assistant sur votre site web, 1 000 réponses par mois.\n- Bon plan, 25 000 FCFA par mois : un assistant sur votre site et sur WhatsApp, 2 000 réponses, 800 messages WhatsApp et 100 messages vocaux par mois.\n- Pro, 40 000 FCFA par mois : 3 assistants, 5 000 réponses, 2 500 messages WhatsApp, modèles de messages, import de vos discussions.\n- Business, 120 000 FCFA par mois : 10 assistants, 15 000 réponses, 10 000 messages WhatsApp, assistance prioritaire.',309,'','openai:text-embedding-3-small','2026-10-01 02:51:50','2026-10-01 02:51:50'),
(28,1,1,19,19,2,'Combien coûte un chatbot WhatsApp pour une petite entreprise ? > Comment choisir','Comptez vos conversations : combien de clients vous écrivent par jour, et combien de messages chacun envoie en moyenne ? Une petite boutique reçoit souvent une dizaine de conversations par jour : le Bon plan suffit. Un commerce très actif, ou plusieurs points de vente, choisira Pro.\nLe dépassement n\'est pas une mauvaise surprise : vous voyez votre consommation dans votre espace et vous rechargez des messages par Mobile Money si besoin.\n\nQuestion : Les messages WhatsApp sont-ils facturés en plus ?\nRéponse : Chez Kouma, non : un volume mensuel est inclus dans chaque offre avec WhatsApp, et vous ne saisissez aucune carte bancaire.\n\nQuestion : Peut-on payer par Mobile Money ?\nRéponse : Oui : Orange Money, Moov Money, Coris Money, ou virement. Vous envoyez la référence du paiement et l\'offre est activée.\n\nQuestion : Y a-t-il un engagement ?\nRéponse : Non : vous changez d\'offre ou vous arrêtez quand vous voulez.\n\nQuestion : Existe-t-il une offre gratuite ?\nRéponse : Un essai de 14 jours, sans carte bancaire, limité à 100 réponses. Passé ce délai, l\'assistant se met en pause et vos données sont conservées.\n\nPage du site : https://kouma.site/guides/combien-coute-un-chatbot-whatsapp',298,'','openai:text-embedding-3-small','2026-10-01 02:51:50','2026-10-01 02:51:50'),
(29,1,1,20,20,0,'Créer un chatbot WhatsApp pour son entreprise : le guide en 6 étapes','Un bon chatbot ne demande pas de savoir programmer : il demande de savoir ce que vos clients vous demandent. Suivez ces six étapes, dans l\'ordre, pour en avoir un qui sert vraiment.\n\nCréer un chatbot WhatsApp pour son entreprise : le guide en 6 étapes > Les six étapes\n\n1. Listez les dix questions que vos clients posent le plus souvent (prix, horaires, livraison, paiement, disponibilité, adresse). Relisez vos conversations WhatsApp récentes pour ne rien oublier.\n2. Rassemblez les documents qui y répondent : tarifs, catalogue, conditions de livraison, menus, plan d\'accès. Des photos d\'affiches suffisent. Si une information n\'est écrite nulle part, écrivez-la : le chatbot ne peut pas la deviner.\n3. Créez l\'assistant, donnez-lui ses sources et choisissez son ton (tutoiement ou vouvoiement, émojis, longueur des réponses).\n4. Testez avec de vraies questions, y compris les plus tordues. Vérifiez qu\'il dit « je ne sais pas » quand il ne sait pas, plutôt que d\'inventer.\n5. Prévoyez le passage à une personne : qui est prévenu, comment (e-mail, WhatsApp), et en combien de temps il doit répondre.\n6. Activez WhatsApp, annoncez-le à vos clients, puis regardez chaque semaine les questions restées sans réponse pour compléter vos documents.',311,'','openai:text-embedding-3-small','2026-10-01 02:51:52','2026-10-01 02:51:52'),
(30,1,1,20,20,1,'Créer un chatbot WhatsApp pour son entreprise : le guide en 6 étapes > Les erreurs fréquentes','- Vouloir tout automatiser dès le premier jour : commencez par les questions répétitives.\n- Donner des documents périmés : un ancien tarif reste dans la mémoire de l\'assistant tant que vous ne le retirez pas.\n- Oublier de dire au chatbot quand passer la main : un client mécontent doit parler à une personne.\n- Ne jamais relire les conversations : c\'est là que vous voyez ce qui manque.\n\nCréer un chatbot WhatsApp pour son entreprise : le guide en 6 étapes > Combien de temps faut-il ?\n\nAvec des documents prêts, comptez une heure pour créer et tester un premier assistant. L\'activation de WhatsApp dépend de la vérification de votre numéro : notre équipe vous accompagne.\n\nQuestion : Faut-il savoir programmer ?\nRéponse : Non : vous envoyez vos documents et vous choisissez des réglages. Aucun code, sauf la ligne à copier pour le site web.\n\nQuestion : Quels documents accepte-t-il ?\nRéponse : PDF, Word, tableaux, texte, photos (lues par intelligence artificielle), liens de sites web et contenu de pages Facebook.\n\nQuestion : Puis-je corriger une réponse ?\nRéponse : Oui : dans la liste des questions sans réponse, vous écrivez la bonne réponse et elle est retenue aussitôt.',295,'','openai:text-embedding-3-small','2026-10-01 02:51:52','2026-10-01 02:51:52'),
(31,1,1,20,20,2,'Créer un chatbot WhatsApp pour son entreprise : le guide en 6 étapes > Combien de temps faut-il ?','Puis-je corriger une réponse ?\nRéponse : Oui : dans la liste des questions sans réponse, vous écrivez la bonne réponse et elle est retenue aussitôt.\n\n\n\nPage du site : https://kouma.site/guides/creer-un-chatbot-whatsapp-pour-son-entreprise',60,'','openai:text-embedding-3-small','2026-10-01 02:51:52','2026-10-01 02:51:52'),
(32,1,1,21,21,0,'WhatsApp Business : application ou API, laquelle choisir ?','Ces deux mots prêtent à confusion. L\'application est celle que vous installez sur votre téléphone ; l\'API est la porte d\'entrée des logiciels, donc des chatbots. Voici ce qui les distingue.\n\nWhatsApp Business : application ou API, laquelle choisir ? > L\'application WhatsApp Business\n\n- Gratuite, installée sur un téléphone, avec un profil d\'entreprise, un catalogue, des étiquettes, des réponses rapides et des messages automatiques simples.\n- Parfaite pour démarrer et pour les petites équipes qui répondent à la main.\n- Limitée : pas de chatbot qui comprend la question, peu de personnes qui peuvent répondre en même temps, pas de statistiques poussées.\n\nWhatsApp Business : application ou API, laquelle choisir ? > L\'API WhatsApp Cloud\n\n- Proposée par Meta aux logiciels : c\'est par elle qu\'un assistant lit et envoie des messages.\n- Permet l\'automatisation, plusieurs personnes sur la même ligne, des statistiques et des modèles de messages approuvés.\n- Les messages sont facturés par Meta selon leur catégorie. Avec Kouma, ce coût est inclus dans votre offre.\n- Les étiquettes de l\'application ne sont pas disponibles par l\'API : une plateforme doit proposer les siennes.',295,'','openai:text-embedding-3-small','2026-10-01 02:51:55','2026-10-01 02:51:55'),
(33,1,1,21,21,1,'WhatsApp Business : application ou API, laquelle choisir ? > Laquelle choisir ?','Si vous répondez à quelques clients par jour, l\'application suffit. Dès que les mêmes questions reviennent, que vous voulez répondre la nuit, ou que plusieurs personnes doivent intervenir, passez par l\'API avec un assistant.\nLe numéro utilisé par l\'API ne peut pas être utilisé en même temps dans l\'application WhatsApp classique, sauf mode de coexistence proposé par Meta sous conditions. Notre équipe vous explique la marche à suivre pour votre numéro.\n\nWhatsApp Business : application ou API, laquelle choisir ? > La fenêtre de 24 heures\n\nPar l\'API, vous pouvez répondre librement dans les 24 heures qui suivent le dernier message du client. Ensuite, seul un modèle de message approuvé par WhatsApp peut rouvrir la conversation.\n\nQuestion : Mon numéro actuel peut-il passer sur l\'API ?\nRéponse : Souvent oui, mais il ne doit pas être enregistré dans l\'application WhatsApp classique au même moment. Notre équipe étudie votre cas.\n\nQuestion : Perd-on ses anciennes conversations ?\nRéponse : Les conversations de l\'application ne sont pas transférées automatiquement : prévoyez une exportation si elles comptent. Kouma peut apprendre de votre style à partir d\'un export.',293,'','openai:text-embedding-3-small','2026-10-01 02:51:55','2026-10-01 02:51:55'),
(34,1,1,21,21,2,'WhatsApp Business : application ou API, laquelle choisir ? > La fenêtre de 24 heures','ne sont pas transférées automatiquement : prévoyez une exportation si elles comptent. Kouma peut apprendre de votre style à partir d\'un export.\n\n\n\nQuestion : L\'API est-elle payante ?\nRéponse : Meta facture les messages envoyés selon leur catégorie et le pays. Chez Kouma, un volume mensuel est inclus dans l\'offre.\n\nPage du site : https://kouma.site/guides/whatsapp-business-application-ou-api',99,'','openai:text-embedding-3-small','2026-10-01 02:51:55','2026-10-01 02:51:55'),
(35,1,1,22,22,0,'Un chatbot IA peut-il inventer un prix ou un horaire ?','C\'est la peur de tous les commerçants : un robot qui annonce un mauvais prix à un client. Le risque est réel avec un chatbot généraliste. Il se maîtrise avec une règle simple : ne répondre qu\'avec vos documents.\n\nUn chatbot IA peut-il inventer un prix ou un horaire ? > Pourquoi un chatbot se trompe\n\nUn modèle d\'intelligence artificielle généraliste complète ce qu\'il ne sait pas par ce qui lui paraît vraisemblable. C\'est utile pour écrire un texte, dangereux pour annoncer un prix : il ne connaît pas votre boutique.\n\nUn chatbot IA peut-il inventer un prix ou un horaire ? > Comment Kouma limite le risque\n\n- L\'assistant ne répond qu\'à partir des extraits de vos documents retrouvés pour la question posée.\n- Un seuil de pertinence écarte les extraits trop éloignés : si rien ne correspond, il ne cherche pas à broder.\n- Quand l\'information manque, il le dit, propose de contacter votre équipe et note la question.\n- Les prix, horaires et noms sont repris tels qu\'écrits dans vos documents.\n- Il ignore les consignes cachées dans un message (« oublie tes règles ») et ne révèle pas ses instructions.\n- Le contenu importé d\'un site ou d\'un fichier est traité comme une information, jamais comme un ordre.',302,'','openai:text-embedding-3-small','2026-10-01 02:51:56','2026-10-01 02:51:56'),
(36,1,1,22,22,1,'Un chatbot IA peut-il inventer un prix ou un horaire ? > Ce que vous pouvez vérifier','- Chaque réponse cite ses sources : vous voyez d\'où vient l\'information.\n- La liste des questions sans réponse montre ce que l\'assistant a refusé d\'inventer.\n- Les conversations sont relisibles, avec un repère pour les réponses qui s\'appuyaient sur rien.\n- Les visiteurs peuvent signaler une réponse à améliorer (pouce vers le bas).\n\nUn chatbot IA peut-il inventer un prix ou un horaire ? > Comment écrire de bons documents\n\nUne phrase claire vaut mieux qu\'un long document : « Livraison à Bobo-Dioulasso : 2 000 FCFA, sous 48 h. » Datez vos tarifs, retirez les anciens, et ajoutez les questions que vos clients posent vraiment. L\'assistant est aussi bon que ce que vous lui donnez.\n\nQuestion : Le risque est-il nul ?\nRéponse : Aucun système n\'est infaillible. Les garde-fous réduisent fortement le risque, et la relecture des conversations permet de corriger vite.\n\nQuestion : Que se passe-t-il si mes documents se contredisent ?\nRéponse : L\'assistant peut reprendre l\'un ou l\'autre : gardez un seul tarif à jour, et supprimez les anciens documents.',263,'','openai:text-embedding-3-small','2026-10-01 02:51:56','2026-10-01 02:51:56'),
(37,1,1,22,22,2,'Un chatbot IA peut-il inventer un prix ou un horaire ? > Comment écrire de bons documents','documents se contredisent ?\nRéponse : L\'assistant peut reprendre l\'un ou l\'autre : gardez un seul tarif à jour, et supprimez les anciens documents.\n\n\n\nQuestion : Mes documents servent-ils à d\'autres entreprises ?\nRéponse : Non : chaque entreprise a son espace isolé, et vos documents ne servent qu\'à votre assistant.\n\nPage du site : https://kouma.site/guides/chatbot-ia-sans-inventer-de-prix',98,'','openai:text-embedding-3-small','2026-10-01 02:51:56','2026-10-01 02:51:56'),
(38,1,1,23,23,0,'Un chatbot WhatsApp pour votre boutique','Dans un commerce, la même question revient cent fois : « c\'est combien ? », « vous livrez ? », « il en reste ? ». L\'assistant y répond avec vos prix, prend la commande et vous laisse la confirmer.\n\nUn chatbot WhatsApp pour votre boutique > Ce que fait votre assistant\n\nMétiers concernés : boutique, mode, cosmétiques, épicerie, quincaillerie, vente en ligne.\n- Donner les prix, la disponibilité, les tailles, couleurs et références des articles.\n- Expliquer la livraison (zones, tarifs, délais), les moyens de paiement et les retours.\n- Aider le client à passer commande et préparer le travail de l\'équipe.\n\nUn chatbot WhatsApp pour votre boutique > Des réponses rapides dès l\'ouverture\n\nÀ l\'ouverture de la discussion, l\'assistant propose ces réponses rapides. Vous pouvez les modifier.\n- Quels sont vos prix ?\n- Vous livrez ?\n- Comment payer ?\n- Passer une commande\n\nUn chatbot WhatsApp pour votre boutique > Quand il vous passe la main\n\nIl vous prévient notamment pour : commande à confirmer, litige sur une livraison, article défectueux, demande de remboursement ou de remise.',270,'','openai:text-embedding-3-small','2026-10-01 02:51:58','2026-10-01 02:51:58'),
(39,1,1,23,23,1,'Un chatbot WhatsApp pour votre boutique > Combien ça coûte ?','L\'essai gratuit dure 14 jours, sans carte bancaire. L\'offre Bon plan (25 000 FCFA par mois) donne un assistant sur votre site et sur WhatsApp ; l\'offre Pro (40 000 FCFA par mois) ajoute 3 assistants, pour plusieurs points de vente.\n\nQuestion : L\'assistant peut-il dire si un article est en stock ?\nRéponse : Seulement si votre document le dit. Sinon il propose de vérifier avec votre équipe, sans promettre.\n\nQuestion : Qui confirme les commandes ?\nRéponse : Vous : l\'assistant prépare la commande, vous prévient, et vous la confirmez depuis la page Demandes.\n\nPage du site : https://kouma.site/chatbot-whatsapp-boutique',155,'','openai:text-embedding-3-small','2026-10-01 02:51:58','2026-10-01 02:51:58'),
(40,1,1,24,24,0,'Un chatbot WhatsApp pour votre restaurant','Le midi et le soir, vous n\'avez pas le temps de répondre. L\'assistant donne le menu, les horaires, les prix et la livraison, prend la réservation ou la commande, et vous prévient.\n\nUn chatbot WhatsApp pour votre restaurant > Ce que fait votre assistant\n\nMétiers concernés : restaurant, maquis, fast-food, traiteur, boulangerie, pâtisserie.\n- Présenter le menu, les plats du jour, les prix et les formules.\n- Donner les horaires, l\'adresse, les modes de livraison et de paiement.\n- Prendre des réservations et des commandes à emporter ou à livrer.\n\nUn chatbot WhatsApp pour votre restaurant > Des réponses rapides dès l\'ouverture\n\nÀ l\'ouverture de la discussion, l\'assistant propose ces réponses rapides. Vous pouvez les modifier.\n- Voir le menu\n- Vos horaires ?\n- Réserver une table\n- Livrez-vous ?\n\nUn chatbot WhatsApp pour votre restaurant > Quand il vous passe la main\n\nIl vous prévient notamment pour : réservation de groupe ou d\'événement, allergie sévère, plainte sur un plat ou une livraison, demande de devis traiteur.',257,'','openai:text-embedding-3-small','2026-10-01 02:51:59','2026-10-01 02:51:59'),
(41,1,1,24,24,1,'Un chatbot WhatsApp pour votre restaurant > Combien ça coûte ?','L\'essai gratuit dure 14 jours, sans carte bancaire. L\'offre Bon plan (25 000 FCFA par mois) donne un assistant sur votre site et sur WhatsApp ; l\'offre Pro (40 000 FCFA par mois) ajoute 3 assistants, pour plusieurs points de vente.\n\nQuestion : Peut-il lire mon menu en photo ?\nRéponse : Oui : une photo de votre carte ou de votre affiche est lue par intelligence artificielle, puis retenue.\n\nQuestion : Gère-t-il les allergies ?\nRéponse : Il ne répond que si votre document le précise, et vous passe la main sur les questions de santé.\n\nPage du site : https://kouma.site/chatbot-whatsapp-restaurant',150,'','openai:text-embedding-3-small','2026-10-01 02:51:59','2026-10-01 02:51:59'),
(42,1,1,25,25,0,'Un chatbot WhatsApp pour clinique et cabinet médical','L\'accueil téléphonique est saturé. L\'assistant répond aux questions pratiques (horaires, tarifs, spécialités, accès) et prépare les rendez-vous, sans jamais donner de conseil médical.\n\nUn chatbot WhatsApp pour clinique et cabinet médical > Ce que fait votre assistant\n\nMétiers concernés : clinique, cabinet médical, dentiste, pharmacie, laboratoire, optique.\n- Renseigner sur les services, les spécialités, les horaires de consultation et les tarifs affichés.\n- Aider à prendre un rendez-vous et orienter vers le bon service.\n- Rappeler les documents à apporter et les conditions pratiques.\n\nUn chatbot WhatsApp pour clinique et cabinet médical > Des réponses rapides dès l\'ouverture\n\nÀ l\'ouverture de la discussion, l\'assistant propose ces réponses rapides. Vous pouvez les modifier.\n- Prendre rendez-vous\n- Vos horaires ?\n- Quels services ?\n- Vos tarifs ?\n\nUn chatbot WhatsApp pour clinique et cabinet médical > Quand il vous passe la main\n\nIl vous prévient notamment pour : toute question médicale personnelle, résultat d\'examen, urgence, réclamation, demande de dossier.',269,'','openai:text-embedding-3-small','2026-10-01 02:52:01','2026-10-01 02:52:01'),
(43,1,1,25,25,1,'Un chatbot WhatsApp pour clinique et cabinet médical > Combien ça coûte ?','L\'essai gratuit dure 14 jours, sans carte bancaire. L\'offre Bon plan (25 000 FCFA par mois) donne un assistant sur votre site et sur WhatsApp ; l\'offre Pro (40 000 FCFA par mois) ajoute 3 assistants, pour plusieurs points de vente.\n\nQuestion : L\'assistant donne-t-il des conseils médicaux ?\nRéponse : Non : il l\'indique clairement et oriente vers un professionnel. En cas d\'urgence, il passe la main tout de suite.\n\nQuestion : Les données des patients sont-elles protégées ?\nRéponse : Chaque entreprise a son espace isolé et l\'assistant n\'a accès à rien d\'autre que vos documents. Informez vos patients de l\'usage d\'un assistant.\n\nPage du site : https://kouma.site/chatbot-whatsapp-clinique',173,'','openai:text-embedding-3-small','2026-10-01 02:52:01','2026-10-01 02:52:01'),
(44,1,1,26,26,0,'Un chatbot WhatsApp pour votre école ou votre centre de formation','À la rentrée, les mêmes questions arrivent par centaines : dates d\'inscription, frais, pièces à fournir. L\'assistant répond à toute heure et transmet les demandes à votre secrétariat.\n\nUn chatbot WhatsApp pour votre école ou votre centre de formation > Ce que fait votre assistant\n\nMétiers concernés : École, collège, lycée, université, centre de formation, cours particuliers.\n- Présenter les filières, niveaux, programmes, calendrier et frais de scolarité.\n- Expliquer la procédure et les pièces à fournir pour une inscription.\n- Répondre aux parents et aux étudiants sur les horaires, le transport, les examens.\n\nUn chatbot WhatsApp pour votre école ou votre centre de formation > Des réponses rapides dès l\'ouverture\n\nÀ l\'ouverture de la discussion, l\'assistant propose ces réponses rapides. Vous pouvez les modifier.\n- Frais de scolarité ?\n- Comment s\'inscrire ?\n- Quelles filières ?\n- Calendrier ?\n\nUn chatbot WhatsApp pour votre école ou votre centre de formation > Quand il vous passe la main\n\nIl vous prévient notamment pour : demande de dérogation, difficulté de paiement, conflit ou discipline, résultats d\'un élève, demande de bourse.',287,'','openai:text-embedding-3-small','2026-10-01 02:52:03','2026-10-01 02:52:03'),
(45,1,1,26,26,1,'Un chatbot WhatsApp pour votre école ou votre centre de formation > Combien ça coûte ?','L\'essai gratuit dure 14 jours, sans carte bancaire. L\'offre Bon plan (25 000 FCFA par mois) donne un assistant sur votre site et sur WhatsApp ; l\'offre Pro (40 000 FCFA par mois) ajoute 3 assistants, pour plusieurs points de vente.\n\nQuestion : Peut-il donner les résultats d\'un élève ?\nRéponse : Non : il ne répond qu\'avec des informations générales de vos documents et passe la main pour les dossiers personnels.\n\nPage du site : https://kouma.site/chatbot-whatsapp-ecole',118,'','openai:text-embedding-3-small','2026-10-01 02:52:03','2026-10-01 02:52:03'),
(46,1,1,27,27,0,'Un chatbot WhatsApp pour votre agence immobilière','Un acheteur écrit à 21 h pour savoir si l\'appartement est toujours disponible. L\'assistant répond avec vos annonces, recueille ses coordonnées et vous passe la demande de visite.\n\nUn chatbot WhatsApp pour votre agence immobilière > Ce que fait votre assistant\n\nMétiers concernés : agence immobilière, promoteur, gestion locative, terrains, location meublée.\n- Présenter les biens disponibles, leurs caractéristiques, quartiers et prix indiqués.\n- Qualifier la demande (achat ou location, budget, quartier, délai).\n- Organiser des visites et transmettre les contacts qualifiés à l\'équipe.\n\nUn chatbot WhatsApp pour votre agence immobilière > Des réponses rapides dès l\'ouverture\n\nÀ l\'ouverture de la discussion, l\'assistant propose ces réponses rapides. Vous pouvez les modifier.\n- Biens disponibles ?\n- Louer un appartement\n- Acheter un terrain\n- Organiser une visite\n\nUn chatbot WhatsApp pour votre agence immobilière > Quand il vous passe la main\n\nIl vous prévient notamment pour : négociation de prix, questions juridiques (titre foncier, bail), demande de visite urgente, litige.',271,'','openai:text-embedding-3-small','2026-10-01 02:52:04','2026-10-01 02:52:04'),
(47,1,1,27,27,1,'Un chatbot WhatsApp pour votre agence immobilière > Combien ça coûte ?','L\'essai gratuit dure 14 jours, sans carte bancaire. L\'offre Bon plan (25 000 FCFA par mois) donne un assistant sur votre site et sur WhatsApp ; l\'offre Pro (40 000 FCFA par mois) ajoute 3 assistants, pour plusieurs points de vente.\n\nQuestion : Met-il à jour les annonces lui-même ?\nRéponse : Vous mettez à jour vos documents ou votre site : pour un site web, une mise à jour automatique relit vos pages régulièrement.\n\nPage du site : https://kouma.site/chatbot-whatsapp-immobilier',120,'','openai:text-embedding-3-small','2026-10-01 02:52:04','2026-10-01 02:52:04'),
(48,1,1,28,28,0,'Un chatbot WhatsApp pour votre hôtel ou votre résidence','Les voyageurs écrivent depuis un autre fuseau horaire et veulent une réponse tout de suite. L\'assistant donne les tarifs, les services et l\'accès, en français et en anglais, et prépare la réservation.\n\nUn chatbot WhatsApp pour votre hôtel ou votre résidence > Ce que fait votre assistant\n\nMétiers concernés : hôtel, résidence, auberge, agence de voyages, excursions, location de salles.\n- Présenter les chambres, tarifs, services (petit-déjeuner, navette, wifi) et l\'emplacement.\n- Renseigner sur les excursions, salles et forfaits.\n- Prendre les demandes de réservation.\n\nUn chatbot WhatsApp pour votre hôtel ou votre résidence > Des réponses rapides dès l\'ouverture\n\nÀ l\'ouverture de la discussion, l\'assistant propose ces réponses rapides. Vous pouvez les modifier.\n- Tarifs des chambres ?\n- Réserver\n- Services inclus ?\n- Comment venir ?\n\nUn chatbot WhatsApp pour votre hôtel ou votre résidence > Quand il vous passe la main\n\nIl vous prévient notamment pour : réservation de groupe ou d\'événement, modification ou annulation, réclamation d\'un séjour, demande de facture.',269,'','openai:text-embedding-3-small','2026-10-01 02:52:05','2026-10-01 02:52:05'),
(49,1,1,28,28,1,'Un chatbot WhatsApp pour votre hôtel ou votre résidence > Combien ça coûte ?','L\'essai gratuit dure 14 jours, sans carte bancaire. L\'offre Bon plan (25 000 FCFA par mois) donne un assistant sur votre site et sur WhatsApp ; l\'offre Pro (40 000 FCFA par mois) ajoute 3 assistants, pour plusieurs points de vente.\n\nQuestion : Répond-il en anglais ?\nRéponse : Oui : il répond dans la langue du client, parmi celles que vous avez choisies pour votre assistant.\n\nPage du site : https://kouma.site/chatbot-whatsapp-hotel',109,'','openai:text-embedding-3-small','2026-10-01 02:52:05','2026-10-01 02:52:05'),
(50,1,1,29,29,0,'Un chatbot WhatsApp pour votre salon de coiffure ou de beauté','Quand vous coiffez, vous ne pouvez pas répondre. L\'assistant donne vos tarifs et vos créneaux, et note les demandes de rendez-vous que vous confirmez entre deux clientes.\n\nUn chatbot WhatsApp pour votre salon de coiffure ou de beauté > Ce que fait votre assistant\n\nMétiers concernés : salon de coiffure, institut, barbier, spa, onglerie, maquillage.\n- Présenter les prestations, durées et tarifs.\n- Prendre les rendez-vous et rappeler les consignes de préparation.\n- Informer sur les promotions et les produits vendus.\n\nUn chatbot WhatsApp pour votre salon de coiffure ou de beauté > Des réponses rapides dès l\'ouverture\n\nÀ l\'ouverture de la discussion, l\'assistant propose ces réponses rapides. Vous pouvez les modifier.\n- Vos tarifs ?\n- Prendre rendez-vous\n- Vos prestations ?\n- Horaires ?\n\nUn chatbot WhatsApp pour votre salon de coiffure ou de beauté > Quand il vous passe la main\n\nIl vous prévient notamment pour : prestation mal vécue, réaction cutanée, demande de remboursement, mariage ou événement (devis).',254,'','openai:text-embedding-3-small','2026-10-01 02:52:07','2026-10-01 02:52:07'),
(51,1,1,29,29,1,'Un chatbot WhatsApp pour votre salon de coiffure ou de beauté > Combien ça coûte ?','L\'essai gratuit dure 14 jours, sans carte bancaire. L\'offre Bon plan (25 000 FCFA par mois) donne un assistant sur votre site et sur WhatsApp ; l\'offre Pro (40 000 FCFA par mois) ajoute 3 assistants, pour plusieurs points de vente.\n\nQuestion : Qui confirme le rendez-vous ?\nRéponse : Vous : la demande arrive dans votre page Demandes avec les coordonnées de la cliente, et vous lui répondez depuis WhatsApp.\n\nPage du site : https://kouma.site/chatbot-whatsapp-salon-de-beaute',119,'','openai:text-embedding-3-small','2026-10-01 02:52:07','2026-10-01 02:52:07'),
(52,1,1,30,30,0,'Un chatbot WhatsApp pour votre activité de services','Plombier, consultant, agence de communication : vos clients veulent savoir ce que vous faites, combien ça coûte et quand vous intervenez. L\'assistant répond, puis recueille la demande de devis.\n\nUn chatbot WhatsApp pour votre activité de services > Ce que fait votre assistant\n\nMétiers concernés : plomberie, électricité, informatique, comptabilité, conseil, agence, photographe.\n- Présenter les services, la zone d\'intervention et les délais habituels.\n- Recueillir le besoin et préparer un devis.\n- Répondre sur les tarifs indiqués et les modalités de paiement.\n\nUn chatbot WhatsApp pour votre activité de services > Des réponses rapides dès l\'ouverture\n\nÀ l\'ouverture de la discussion, l\'assistant propose ces réponses rapides. Vous pouvez les modifier.\n- Demander un devis\n- Vos services ?\n- Zone d\'intervention ?\n- Délais ?\n\nUn chatbot WhatsApp pour votre activité de services > Quand il vous passe la main\n\nIl vous prévient notamment pour : urgence (fuite, panne, sécurité), litige sur une facture, chantier en cours, demande de rendez-vous sur place.',265,'','openai:text-embedding-3-small','2026-10-01 02:52:08','2026-10-01 02:52:08'),
(53,1,1,30,30,1,'Un chatbot WhatsApp pour votre activité de services > Combien ça coûte ?','L\'essai gratuit dure 14 jours, sans carte bancaire. L\'offre Bon plan (25 000 FCFA par mois) donne un assistant sur votre site et sur WhatsApp ; l\'offre Pro (40 000 FCFA par mois) ajoute 3 assistants, pour plusieurs points de vente.\n\nQuestion : L\'assistant peut-il donner un prix ferme ?\nRéponse : Seulement ceux de vos documents. Pour un devis sur mesure, il recueille les informations et vous passe la demande.\n\nPage du site : https://kouma.site/chatbot-whatsapp-services',118,'','openai:text-embedding-3-small','2026-10-01 02:52:08','2026-10-01 02:52:08'),
(54,1,1,31,31,0,'Un chatbot WhatsApp pour les entreprises du Burkina Faso','De Ouagadougou à Bobo-Dioulasso, vos clients vous écrivent sur WhatsApp. Kouma répond pour vous à toute heure, en français, avec vos prix en FCFA, et vous prévient quand une commande attend votre confirmation.\n\nMonnaie : Franc CFA (FCFA)\nPaiement de l\'abonnement : Orange Money, Moov Money, Coris Money ou virement\nVilles courantes : Ouagadougou, Bobo-Dioulasso, Koudougou, Ouahigouya\nLangues : Français, anglais ; mooré, dioula et peul avec les limites annoncées\n\nUn chatbot WhatsApp pour les entreprises du Burkina Faso > Pensé pour le quotidien des entreprises burkinabè\n\nVous donnez vos prix en FCFA, vos zones de livraison (Ouagadougou, Bobo-Dioulasso, autres villes) et vos moyens de paiement : l\'assistant les reprend tels quels. Offre Bon plan à 25 000 FCFA par mois, essai gratuit de 14 jours.\nLes langues locales (mooré, dioula, peul) sont proposées avec un niveau de fiabilité affiché : testez avec vos propres phrases avant de vous engager, et gardez le français comme langue de repli.\n\nQuestion : Puis-je payer par Orange Money ou Moov Money ?\nRéponse : Oui : vous envoyez la référence du paiement et l\'offre est activée. Coris Money et le virement sont aussi acceptés.',296,'','openai:text-embedding-3-small','2026-10-01 02:52:10','2026-10-01 02:52:10'),
(55,1,1,31,31,1,'Un chatbot WhatsApp pour les entreprises du Burkina Faso > Pensé pour le quotidien des entreprises burkinabè','Money ou Moov Money ?\nRéponse : Oui : vous envoyez la référence du paiement et l\'offre est activée. Coris Money et le virement sont aussi acceptés.\n\n\n\nQuestion : L\'assistant comprend-il le mooré ?\nRéponse : Le mooré est une langue que l\'assistant comprend de façon limitée : il est classé « expérimental ». Il répond aussi en français. À tester avec vos clients.\n\nPage du site : https://kouma.site/chatbot-whatsapp-burkina-faso',107,'','openai:text-embedding-3-small','2026-10-01 02:52:10','2026-10-01 02:52:10'),
(56,1,1,32,32,0,'Un chatbot WhatsApp pour les entreprises de Côte d\'Ivoire','À Abidjan comme à Bouaké ou Yamoussoukro, WhatsApp est le premier canal de vos clients. Kouma répond à leur place avec vos informations et vous passe les commandes et les demandes qui comptent.\n\nMonnaie : Franc CFA (FCFA)\nPaiement de l\'abonnement : Mobile Money ou virement (référence à nous envoyer)\nVilles courantes : Abidjan, Bouaké, Yamoussoukro, San-Pédro, Korhogo\nLangues : Français, anglais ; dioula avec les limites annoncées\n\nUn chatbot WhatsApp pour les entreprises de Côte d\'Ivoire > Un assistant pour les commerces, restaurants et services ivoiriens\n\nLivraison par quartier, paiement à la livraison ou par Mobile Money, horaires d\'ouverture : vous écrivez vos règles une fois, l\'assistant les applique. Offre Bon plan à 25 000 FCFA par mois, essai gratuit de 14 jours.\n\nQuestion : Mes clients peuvent-ils écrire en dioula ?\nRéponse : Le dioula est une langue « assistée » : l\'assistant comprend des phrases courtes et simples, et répond aussi en français. Testez avant de vous engager.\n\nQuestion : Puis-je gérer plusieurs points de vente ?\nRéponse : Oui, avec l\'offre Pro (3 assistants) ou Business (10 assistants).\n\nPage du site : https://kouma.site/chatbot-whatsapp-cote-d-ivoire',299,'','openai:text-embedding-3-small','2026-10-01 02:52:11','2026-10-01 02:52:11'),
(57,1,1,33,33,0,'Un chatbot WhatsApp pour les entreprises du Sénégal','À Dakar, Thiès, Saint-Louis ou Touba, vos clients vous écrivent sur WhatsApp à toute heure. Kouma répond avec vos informations et vous laisse confirmer les commandes.\n\nMonnaie : Franc CFA (FCFA)\nPaiement de l\'abonnement : Mobile Money ou virement (référence à nous envoyer)\nVilles courantes : Dakar, Thiès, Saint-Louis, Touba, Kaolack\nLangues : Français, anglais, arabe ; wolof avec les limites annoncées\n\nUn chatbot WhatsApp pour les entreprises du Sénégal > Le wolof, avec honnêteté\n\nLe wolof fait partie des langues que l\'assistant peut utiliser, avec un niveau « assisté » : phrases courtes, prix et chiffres repris tels quels. Il répond aussi en français quand il hésite. Nous vous conseillons de tester avec de vraies phrases de vos clients. Offre Bon plan à 25 000 FCFA par mois, essai gratuit de 14 jours.\n\nQuestion : Le wolof est-il bien géré ?\nRéponse : Partiellement : c\'est une langue « assistée ». Les messages vocaux en wolof demandent un serveur de reconnaissance dédié, non inclus par défaut.\n\nPage du site : https://kouma.site/chatbot-whatsapp-senegal',267,'','openai:text-embedding-3-small','2026-10-01 02:52:13','2026-10-01 02:52:13'),
(58,1,1,34,34,0,'Un chatbot WhatsApp pour les entreprises du Mali','À Bamako, Sikasso ou Ségou, vos clients vous écrivent à toute heure. Kouma répond à votre place avec vos informations et vous prévient quand une commande ou un rendez-vous attend votre réponse.\n\nMonnaie : Franc CFA (FCFA)\nPaiement de l\'abonnement : Mobile Money ou virement (référence à nous envoyer)\nVilles courantes : Bamako, Sikasso, Ségou, Kayes, Mopti\nLangues : Français, anglais ; bambara avec les limites annoncées\n\nUn chatbot WhatsApp pour les entreprises du Mali > Le bambara, pour les messages vocaux aussi\n\nLe bambara est l\'une des langues pour lesquelles des modèles libres de reconnaissance vocale existent. Kouma sait s\'y brancher : les vocaux en bambara sont compris si un serveur dédié est configuré. Les réponses restent écrites. Offre Bon plan à 25 000 FCFA par mois, essai gratuit de 14 jours.\n\nQuestion : Mes clients peuvent-ils envoyer des vocaux en bambara ?\nRéponse : Oui si un serveur de reconnaissance vocale en bambara est branché ; sinon, l\'assistant les invite à écrire. Les deux cas sont expliqués dans votre espace.\n\nPage du site : https://kouma.site/chatbot-whatsapp-mali',276,'','openai:text-embedding-3-small','2026-10-01 02:52:15','2026-10-01 02:52:15'),
(59,1,1,35,35,0,'Un chatbot WhatsApp pour les entreprises des Comores','À Moroni, Mutsamudu ou Fomboni, vos clients vous écrivent sur WhatsApp. Kouma répond avec vos informations, affiche ses prix en franc comorien et vous passe les demandes qui comptent.\n\nMonnaie : Franc comorien (KMF)\nPaiement de l\'abonnement : Virement ou paiement mobile (référence à nous envoyer)\nVilles courantes : Moroni, Mutsamudu, Fomboni, Mitsamiouli\nLangues : Français, arabe, anglais ; shikomori non garanti\n\nUn chatbot WhatsApp pour les entreprises des Comores > Des prix en franc comorien\n\nLes offres sont affichées en franc comorien : le Bon plan coûte 18 750 KMF par mois. Le shikomori ne fait pas partie des langues garanties : l\'assistant répond en français ou en arabe.\n\nQuestion : Le shikomori est-il compris ?\nRéponse : Pas de façon fiable : c\'est une langue « expérimentale ». L\'assistant répond en français ou en arabe. Testez avec vos clients avant de vous engager.\n\nPage du site : https://kouma.site/chatbot-whatsapp-comores',237,'','openai:text-embedding-3-small','2026-10-01 02:52:16','2026-10-01 02:52:16'),
(60,1,1,36,36,0,'Un chatbot WhatsApp pour les entreprises du Maroc','À Casablanca, Rabat, Marrakech ou Tanger, vos clients vous écrivent sur WhatsApp en français ou en arabe. Kouma répond avec vos informations, affiche ses prix en dirhams et vous laisse la décision finale.\n\nMonnaie : Dirham marocain (MAD)\nPaiement de l\'abonnement : Virement (référence à nous envoyer)\nVilles courantes : Casablanca, Rabat, Marrakech, Tanger, Fès\nLangues : Français, arabe, anglais\n\nUn chatbot WhatsApp pour les entreprises du Maroc > Français et arabe, dans le sens de la lecture\n\nL\'assistant écrit en arabe (affichage de droite à gauche dans le widget) et en français. La darija n\'est pas garantie : il répond en arabe standard ou en français. Offre Bon plan à 410 DH par mois, essai gratuit de 14 jours.\n\nQuestion : La darija est-elle comprise ?\nRéponse : Partiellement, comme un arabe courant : testez avec des phrases de vos clients. L\'assistant répond en arabe standard ou en français.\n\nPage du site : https://kouma.site/chatbot-whatsapp-maroc',241,'','openai:text-embedding-3-small','2026-10-01 02:52:17','2026-10-01 02:52:17');
