(2,'essentiel','business','Essentiel','Votre assistant sur votre site web','{\"XOF\":10000,\"KMF\":7500,\"EUR\":15,\"USD\":17,\"MAD\":165}',1,NULL,'{\"bots\":1,\"sources\":20,\"pages_per_crawl\":50,\"messages_per_month\":1000,\"members\":2,\"whatsapp_messages_per_month\":0,\"voice_per_month\":0}','{\"whatsapp\":false,\"templates\":false,\"remove_branding\":false,\"priority_support\":false,\"voice\":false,\"chat_import\":false,\"api\":false}',1,0,0,2,'2026-10-01 02:29:52','2026-10-01 02:29:52'),
(3,'pro','business','Pro','Pour une activité qui reçoit beaucoup de messages','{\"XOF\":40000,\"KMF\":30000,\"EUR\":60,\"USD\":70,\"MAD\":660}',1,NULL,'{\"bots\":3,\"sources\":60,\"pages_per_crawl\":200,\"messages_per_month\":5000,\"members\":5,\"whatsapp_messages_per_month\":2500,\"voice_per_month\":300}','{\"whatsapp\":true,\"templates\":true,\"remove_branding\":true,\"priority_support\":false,\"voice\":true,\"chat_import\":true,\"api\":false}',1,0,1,4,'2026-10-01 02:29:52','2026-10-01 02:29:52'),
(4,'business','business','Business','Plusieurs assistants, une équipe, un suivi dédié','{\"XOF\":120000,\"KMF\":90000,\"EUR\":180,\"USD\":205,\"MAD\":1975}',1,NULL,'{\"bots\":10,\"sources\":300,\"pages_per_crawl\":500,\"messages_per_month\":15000,\"members\":15,\"whatsapp_messages_per_month\":10000,\"voice_per_month\":1500}','{\"whatsapp\":true,\"templates\":true,\"remove_branding\":true,\"priority_support\":true,\"voice\":true,\"chat_import\":true,\"api\":false}',1,0,0,5,'2026-10-01 02:29:52','2026-10-01 02:29:52'),
(5,'api','developer','API Développeur','Intégrez l\'assistant dans votre application','{\"XOF\":20000,\"KMF\":15000,\"EUR\":30,\"USD\":35,\"MAD\":330}',1,NULL,'{\"bots\":3,\"sources\":40,\"pages_per_crawl\":100,\"messages_per_month\":3000,\"members\":3,\"whatsapp_messages_per_month\":0,\"voice_per_month\":0}','{\"whatsapp\":false,\"templates\":false,\"remove_branding\":true,\"priority_support\":false,\"voice\":false,\"chat_import\":false,\"api\":true}',1,0,0,20,'2026-10-01 02:29:53','2026-10-01 02:29:53'),
(6,'bonplan','business','Bon plan','Un assistant complet, sur votre site et WhatsApp, au juste prix','{\"XOF\":25000,\"KMF\":18750,\"EUR\":38,\"USD\":43,\"MAD\":410}',1,NULL,'{\"bots\":1,\"sources\":40,\"pages_per_crawl\":100,\"messages_per_month\":2000,\"members\":3,\"whatsapp_messages_per_month\":800,\"voice_per_month\":100}','{\"whatsapp\":true,\"templates\":false,\"remove_branding\":false,\"priority_support\":false,\"voice\":true,\"chat_import\":false,\"api\":false}',1,0,0,3,'2026-10-01 02:29:54','2026-10-01 02:29:54');
